    40	function DistanceRequestFooter({waypoints, transaction, mapboxAccessToken, navigateToWaypointEditPage}: DistanceRequestFooterProps) {
    41	    const theme = useTheme();
    42	    const styles = useThemeStyles();
    43	    const {translate} = useLocalize();
    44	
    45	    const numberOfWaypoints = Object.keys(waypoints ?? {}).length;
    46	    const numberOfFilledWaypoints = Object.values(waypoints ?? {}).filter((waypoint) => waypoint?.address).length;
    47	    const lastWaypointIndex = numberOfWaypoints - 1;
    48	
    49	    const getMarkerComponent = useCallback(
    50	        (icon: IconAsset): ReactNode => (
    51	            <ImageSVG
    52	                src={icon}
    53	                width={CONST.MAP_MARKER_SIZE}
    54	                height={CONST.MAP_MARKER_SIZE}
    55	                fill={theme.icon}
    56	            />
    57	        ),
    58	        [theme],
    59	    );
    60	
    61	    const waypointMarkers = useMemo(
    62	        () =>
    63	            Object.entries(waypoints ?? {})
    64	                .map(([key, waypoint]) => {
    65	                    if (!waypoint?.lat || !waypoint?.lng) {
    66	                        return;
    67	                    }
    68	
    69	                    const index = TransactionUtils.getWaypointIndex(key);
    70	                    let MarkerComponent: IconAsset;
    71	                    if (index === 0) {
    72	                        MarkerComponent = Expensicons.DotIndicatorUnfilled;
    73	                    } else if (index === lastWaypointIndex) {
    74	                        MarkerComponent = Expensicons.Location;
    75	                    } else {
    76	                        MarkerComponent = Expensicons.DotIndicator;
    77	                    }
    78	
    79	                    return {
    80	                        id: `${waypoint.lng},${waypoint.lat},${index}`,
    81	                        coordinate: [waypoint.lng, waypoint.lat] as const,
    82	                        markerComponent: (): ReactNode => getMarkerComponent(MarkerComponent),
    83	                    };
    84	                })
    85	                .filter((waypoint): waypoint is WayPoint => !!waypoint),
    86	        [waypoints, lastWaypointIndex, getMarkerComponent],
    87	    );
    88	
    89	    return (
    90	        <>
    91	            {numberOfFilledWaypoints >= 2 && (
    92	                <View style={[styles.flexRow, styles.justifyContentCenter, styles.pt1]}>
    93	                    <Button
    94	                        small
    95	                        icon={Expensicons.Plus}
    96	                        onPress={() => navigateToWaypointEditPage(Object.keys(transaction?.comment?.waypoints ?? {}).length)}
    97	                        text={translate('distance.addStop')}
    98	                        isDisabled={numberOfWaypoints === MAX_WAYPOINTS}
    99	                        innerStyles={[styles.pl10, styles.pr10]}
   100	                    />
   101	                </View>
   102	            )}
   103	            <View style={styles.mapViewContainer}>
   104	                <DistanceMapView
   105	                    accessToken={mapboxAccessToken?.token ?? ''}
   106	                    mapPadding={CONST.MAPBOX.PADDING}
   107	                    pitchEnabled={false}
   108	                    initialState={{
   109	                        zoom: CONST.MAPBOX.DEFAULT_ZOOM,
   110	                        location: waypointMarkers?.[0]?.coordinate ?? (CONST.MAPBOX.DEFAULT_COORDINATE as [number, number]),
   111	                    }}
   112	                    directionCoordinates={(transaction?.routes?.route0?.geometry?.coordinates as Array<[number, number]>) ?? []}
   113	                    style={[styles.mapView, styles.mapEditView]}
   114	                    waypoints={waypointMarkers}
   115	                    styleURL={CONST.MAPBOX.STYLE_URL}
   116	                    overlayStyle={styles.mapEditView}
   117	                />
   118	            </View>
   119	        </>
   120	    );
   121	}
   122	
   123	DistanceRequestFooter.displayName = 'DistanceRequestFooter';
   124	
   125	export default withOnyx<DistanceRequestFooterProps, DistanceRequestFooterOnyxProps>({
   126	    mapboxAccessToken: {
   127	        key: ONYXKEYS.MAPBOX_ACCESS_TOKEN,
   128	    },
   129	})(DistanceRequestFooter);
