     9	import type Policy from '@src/types/onyx/Policy';
    10	import {isEmptyObject} from '@src/types/utils/EmptyObject';
    11	import * as CurrencyUtils from './CurrencyUtils';
    12	import * as PolicyUtils from './PolicyUtils';
    13	import * as ReportConnection from './ReportConnection';
    14	import * as ReportUtils from './ReportUtils';
    15	
    16	type MileageRate = {
    17	    customUnitRateID?: string;
    18	    rate?: number;
    19	    currency?: string;
    20	    unit: Unit;
    21	    name?: string;
    22	    enabled?: boolean;
    23	};
    24	
    25	let lastSelectedDistanceRates: OnyxEntry<LastSelectedDistanceRates> = {};
    26	Onyx.connect({
    27	    key: ONYXKEYS.NVP_LAST_SELECTED_DISTANCE_RATES,
    28	    callback: (value) => {
    29	        lastSelectedDistanceRates = value;
    30	    },
    31	});
    32	
    33	const METERS_TO_KM = 0.001; // 1 kilometer is 1000 meters
    34	const METERS_TO_MILES = 0.000621371; // There are approximately 0.000621371 miles in a meter
    35	
    36	function getMileageRates(policy: OnyxInputOrEntry<Policy>, includeDisabledRates = false, selectedRateID?: string): Record<string, MileageRate> {
    37	    const mileageRates: Record<string, MileageRate> = {};
    38	
    39	    if (!policy?.customUnits) {
    40	        return mileageRates;
    41	    }
    42	
    43	    const distanceUnit = PolicyUtils.getCustomUnit(policy);
    44	    if (!distanceUnit?.rates) {
    45	        return mileageRates;
    46	    }
    47	
    48	    Object.entries(distanceUnit.rates).forEach(([rateID, rate]) => {
    49	        if (!includeDisabledRates && rate.enabled === false && (!selectedRateID || rateID !== selectedRateID)) {
    50	            return;
    51	        }
    52	
    53	        mileageRates[rateID] = {
    54	            rate: rate.rate,
    55	            currency: rate.currency,
    56	            unit: distanceUnit.attributes.unit,
    57	            name: rate.name,
    58	            customUnitRateID: rate.customUnitRateID,
    59	            enabled: rate.enabled,
    60	        };
    61	    });
    62	
    63	    return mileageRates;
    64	}
    65	
    66	/**
    67	 * Retrieves the default mileage rate based on a given policy.
    68	 *
    69	 * @param policy - The policy from which to extract the default mileage rate.
    70	 *
    71	 * @returns An object containing the rate and unit for the default mileage or null if not found.
    72	 * @returns [rate] - The default rate for the mileage.
    73	 * @returns [currency] - The currency associated with the rate.
    74	 * @returns [unit] - The unit of measurement for the distance.
    75	 */
    76	function getDefaultMileageRate(policy: OnyxInputOrEntry<Policy>): MileageRate | undefined {
    77	    if (isEmptyObject(policy) || !policy?.customUnits) {
    78	        return undefined;
    79	    }
    80	
    81	    const distanceUnit = PolicyUtils.getCustomUnit(policy);
    82	    if (!distanceUnit?.rates) {
    83	        return;
    84	    }
    85	    const mileageRates = Object.values(getMileageRates(policy));
    86	
    87	    const distanceRate = mileageRates.find((rate) => rate.name === CONST.CUSTOM_UNITS.DEFAULT_RATE) ?? mileageRates[0] ?? {};
    88	
    89	    return {
    90	        customUnitRateID: distanceRate.customUnitRateID,
    91	        rate: distanceRate.rate,
    92	        currency: distanceRate.currency,
    93	        unit: distanceUnit.attributes.unit,
    94	        name: distanceRate.name,
    95	    };
    96	}
    97	
    98	/**
    99	 * Converts a given distance in meters to the specified unit (kilometers or miles).
   100	 *
   101	 * @param distanceInMeters - The distance in meters to be converted.
   102	 * @param unit - The desired unit of conversion, either 'km' for kilometers or 'mi' for miles.
   103	 *
   104	 * @returns The converted distance in the specified unit.
   105	 */
   106	function convertDistanceUnit(distanceInMeters: number, unit: Unit): number {
   107	    switch (unit) {
   108	        case CONST.CUSTOM_UNITS.DISTANCE_UNIT_KILOMETERS:
   109	            return distanceInMeters * METERS_TO_KM;
   110	        case CONST.CUSTOM_UNITS.DISTANCE_UNIT_MILES:
   111	            return distanceInMeters * METERS_TO_MILES;
   112	        default:
   113	            throw new Error('Unsupported unit. Supported units are "mi" or "km".');
   114	    }
   115	}
   116	
   117	/**
   118	 * @param distanceInMeters Distance traveled
   119	 * @param unit Unit that should be used to display the distance
   120	 * @returns The distance in requested units, rounded to 2 decimals
   121	 */
   122	function getRoundedDistanceInUnits(distanceInMeters: number, unit: Unit): string {
   123	    const convertedDistance = convertDistanceUnit(distanceInMeters, unit);
   124	    return convertedDistance.toFixed(2);
   125	}
   126	
   127	/**
   128	 * @param unit Unit that should be used to display the distance
   129	 * @param rate Expensable amount allowed per unit
   130	 * @param currency The currency associated with the rate
   131	 * @param translate Translate function
   132	 * @param toLocaleDigit Function to convert to localized digit
   133	 * @param useShortFormUnit If true, the unit will be returned in short form (e.g., "mi", "km").
   134	 * @returns A string that displays the rate used for expense calculation
   135	 */
   136	function getRateForDisplay(
   137	    unit: Unit | undefined,
   138	    rate: number | undefined,
   139	    currency: string | undefined,
   140	    translate: LocaleContextProps['translate'],
   141	    toLocaleDigit: LocaleContextProps['toLocaleDigit'],
   142	    isOffline?: boolean,
   143	    useShortFormUnit?: boolean,
   144	): string {
   145	    if (isOffline && !rate) {
   146	        return translate('iou.defaultRate');
   147	    }
   148	    if (!rate || !currency || !unit) {
   149	        return translate('iou.fieldPending');
   150	    }
   151	
   152	    const singularDistanceUnit = unit === CONST.CUSTOM_UNITS.DISTANCE_UNIT_MILES ? translate('common.mile') : translate('common.kilometer');
   153	    const formattedRate = PolicyUtils.getUnitRateValue(toLocaleDigit, {rate}, useShortFormUnit);
   154	    // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
   155	    const currencySymbol = CurrencyUtils.getCurrencySymbol(currency) || `${currency} `;
   156	
   157	    return `${currencySymbol}${formattedRate} / ${useShortFormUnit ? unit : singularDistanceUnit}`;
   158	}
   159	
   160	/**
   161	 * @param hasRoute Whether the route exists for the distance expense
   162	 * @param distanceInMeters Distance traveled
   163	 * @param unit Unit that should be used to display the distance
   164	 * @param rate Expensable amount allowed per unit
   165	 * @param translate Translate function
   166	 * @param useShortFormUnit If true, the unit will be returned in short form (e.g., "mi", "km").
   167	 * @returns A string that describes the distance traveled
   168	 */
   169	function getDistanceForDisplay(
   170	    hasRoute: boolean,
   171	    distanceInMeters: number,
   172	    unit: Unit | undefined,
   173	    rate: number | undefined,
   174	    translate: LocaleContextProps['translate'],
   175	    useShortFormUnit?: boolean,
   176	): string {
   177	    if (!hasRoute || !rate || !unit || !distanceInMeters) {
   178	        return translate('iou.fieldPending');
   179	    }
   180	
   181	    const distanceInUnits = getRoundedDistanceInUnits(distanceInMeters, unit);
   182	    if (useShortFormUnit) {
   183	        return `${distanceInUnits} ${unit}`;
   184	    }
   185	
   186	    const distanceUnit = unit === CONST.CUSTOM_UNITS.DISTANCE_UNIT_MILES ? translate('common.miles') : translate('common.kilometers');
   187	    const singularDistanceUnit = unit === CONST.CUSTOM_UNITS.DISTANCE_UNIT_MILES ? translate('common.mile') : translate('common.kilometer');
   188	    const unitString = distanceInUnits === '1' ? singularDistanceUnit : distanceUnit;
   189	
   190	    return `${distanceInUnits} ${unitString}`;
   191	}
   192	
   193	/**
   194	 * @param hasRoute Whether the route exists for the distance expense
   195	 * @param distanceInMeters Distance traveled
   196	 * @param unit Unit that should be used to display the distance
   197	 * @param rate Expensable amount allowed per unit
   198	 * @param currency The currency associated with the rate
   199	 * @param translate Translate function
   200	 * @param toLocaleDigit Function to convert to localized digit
   201	 * @returns A string that describes the distance traveled and the rate used for expense calculation
   202	 */
   203	function getDistanceMerchant(
   204	    hasRoute: boolean,
   205	    distanceInMeters: number,
   206	    unit: Unit | undefined,
   207	    rate: number | undefined,
   208	    currency: string,
   209	    translate: LocaleContextProps['translate'],
   210	    toLocaleDigit: LocaleContextProps['toLocaleDigit'],
   211	): string {
   212	    if (!hasRoute || !rate) {
   213	        return translate('iou.fieldPending');
   214	    }
   215	
   216	    const distanceInUnits = getDistanceForDisplay(hasRoute, distanceInMeters, unit, rate, translate, true);
   217	    const ratePerUnit = getRateForDisplay(unit, rate, currency, translate, toLocaleDigit, undefined, true);
   218	
   219	    return `${distanceInUnits} @ ${ratePerUnit}`;
   220	}
   221	
   222	/**
   223	 * Retrieves the rate and unit for a P2P distance expense for a given currency.
   224	 *
   225	 * @param currency
   226	 * @returns The rate and unit in RateAndUnit object.
   227	 */
   228	function getRateForP2P(currency: string): RateAndUnit {
   229	    const currencyWithExistingRate = CONST.CURRENCY_TO_DEFAULT_MILEAGE_RATE[currency] ? currency : CONST.CURRENCY.USD;
   230	    return {
   231	        ...CONST.CURRENCY_TO_DEFAULT_MILEAGE_RATE[currencyWithExistingRate],
   232	        currency: currencyWithExistingRate,
   233	    };
   234	}
   235	
   236	/**
   237	 * Calculates the expense amount based on distance, unit, and rate.
   238	 *
   239	 * @param distance - The distance traveled in meters
   240	 * @param unit - The unit of measurement for the distance
   241	 * @param rate - Rate used for calculating the expense amount
   242	 * @returns The computed expense amount (rounded) in "cents".
   243	 */
   244	function getDistanceRequestAmount(distance: number, unit: Unit, rate: number): number {
   245	    const convertedDistance = convertDistanceUnit(distance, unit);
   246	    const roundedDistance = parseFloat(convertedDistance.toFixed(2));
   247	    return Math.round(roundedDistance * rate);
   248	}
   249	
   250	/**
   251	 * Converts the distance from kilometers or miles to meters.
   252	 *
   253	 * @param distance - The distance to be converted.
   254	 * @param unit - The unit of measurement for the distance.
   255	 * @returns The distance in meters.
   256	 */
   257	function convertToDistanceInMeters(distance: number, unit: Unit): number {
   258	    if (unit === CONST.CUSTOM_UNITS.DISTANCE_UNIT_KILOMETERS) {
   259	        return distance / METERS_TO_KM;
   260	    }
   261	    return distance / METERS_TO_MILES;
   262	}
