   264	/**
   265	 * Returns custom unit rate ID for the distance transaction
   266	 */
   267	function getCustomUnitRateID(reportID: string, shouldUseDefault?: boolean) {
   268	    const allReports = ReportConnection.getAllReports();
   269	    const report = allReports?.[`${ONYXKEYS.COLLECTION.REPORT}${reportID}`];
   270	    const parentReport = allReports?.[`${ONYXKEYS.COLLECTION.REPORT}${report?.parentReportID}`];
   271	    const policy = PolicyUtils.getPolicy(report?.policyID ?? parentReport?.policyID ?? '-1');
   272	    let customUnitRateID: string = CONST.CUSTOM_UNITS.FAKE_P2P_ID;
   273	
   274	    if (ReportUtils.isPolicyExpenseChat(report) || ReportUtils.isPolicyExpenseChat(parentReport)) {
   275	        const distanceUnit = Object.values(policy?.customUnits ?? {}).find((unit) => unit.name === CONST.CUSTOM_UNITS.NAME_DISTANCE);
   276	        const lastSelectedDistanceRateID = lastSelectedDistanceRates?.[policy?.id ?? '-1'] ?? '-1';
   277	        const lastSelectedDistanceRate = distanceUnit?.rates[lastSelectedDistanceRateID] ?? {};
   278	        if (lastSelectedDistanceRate.enabled && lastSelectedDistanceRateID && !shouldUseDefault) {
   279	            customUnitRateID = lastSelectedDistanceRateID;
   280	        } else {
   281	            customUnitRateID = getDefaultMileageRate(policy)?.customUnitRateID ?? '-1';
   282	        }
   283	    }
   284	
   285	    return customUnitRateID;
   286	}
   287	
   288	/**
   289	 * Get taxable amount from a specific distance rate, taking into consideration the tax claimable amount configured for the distance rate
   290	 */
   291	function getTaxableAmount(policy: OnyxEntry<Policy>, customUnitRateID: string, distance: number) {
   292	    const distanceUnit = PolicyUtils.getCustomUnit(policy);
   293	    const customUnitRate = PolicyUtils.getCustomUnitRate(policy, customUnitRateID);
   294	    if (!distanceUnit || !distanceUnit?.customUnitID || !customUnitRate) {
   295	        return 0;
   296	    }
   297	    const unit = distanceUnit?.attributes?.unit ?? CONST.CUSTOM_UNITS.DISTANCE_UNIT_MILES;
   298	    const rate = customUnitRate?.rate ?? 0;
   299	    const amount = getDistanceRequestAmount(distance, unit, rate);
   300	    const taxClaimablePercentage = customUnitRate.attributes?.taxClaimablePercentage ?? 0;
   301	    return amount * taxClaimablePercentage;
   302	}
   303	
   304	export default {
   305	    getDefaultMileageRate,
   306	    getDistanceMerchant,
   307	    getDistanceRequestAmount,
   308	    getRateForDisplay,
   309	    getMileageRates,
   310	    getDistanceForDisplay,
   311	    getRateForP2P,
   312	    getCustomUnitRateID,
   313	    convertToDistanceInMeters,
   314	    getTaxableAmount,
   315	};
